/** SPARQL lowering and generated execution of wide residual filters inside existential witnesses. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeFlatResidualSemanticsTest {
	private static final String NS = "urn:flat-residual:";
	private static final String PREFIX = "PREFIX ex: <" + NS + "> ";
	private static final String CHAIN = "?s ex:p ?a . ?a ex:q ?b . ?b ex:r ?c . ?c ex:t ?d . ";
	private static final String FILTER = "FILTER(STRLEN(CONCAT(STR(?a), STR(?b), STR(?c), STR(?d))) > 0 "
			+ "&& ?d != ex:rejected) ";
	private static final Map<String, String> PROPERTIES = Map.of(
			"rdf4j.lmdb.nativeQueryEngine.enabled", "true", "rdf4j.lmdb.janinoCodegen.enabled", "true",
			"rdf4j.lmdb.janinoCodegen.synchronous", "true", "rdf4j.lmdb.janinoCodegen.thresholdRows", "0",
			"rdf4j.lmdb.janinoCodegen.failOnError", "true", "rdf4j.lmdb.kernelInterpreter.enabled", "true",
			"rdf4j.lmdb.directAdjacency.synchronousMaintenance", "true");

	@Test
	void wideResidualWitnessesMatchOrdinaryResults(@TempDir File directory) throws Exception {
		Map<String, String> previous = new LinkedHashMap<>();
		PROPERTIES.forEach((name, value) -> {
			previous.put(name, System.getProperty(name));
			System.setProperty(name, value);
		});
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		SailRepository lmdb = new SailRepository(store);
		SailRepository memory = new SailRepository(new MemoryStore());
		try {
			populate(lmdb);
			populate(memory);
			assertTrue(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS));
			List<String> witnesses = List.of("EXISTS { " + CHAIN + FILTER + "}",
					"NOT EXISTS { " + CHAIN + FILTER + "}",
					"EXISTS { ?s ex:p ?a . FILTER EXISTS { ?a ex:q ?b . ?b ex:r ?c . ?c ex:t ?d . "
							+ FILTER + "} }");
			for (int i = 0; i < witnesses.size(); i++) {
				String query = PREFIX + "SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE { ?s a ex:C . FILTER "
						+ witnesses.get(i) + " }";
				System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
				List<BindingSet> expected = rows(memory, query, null);
				assertEquals(i == 1 ? "2" : "3", expected.get(0).getValue("n").stringValue());
				assertEquals(expected, rows(lmdb, query, null));
				System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
				assertEquals(expected, rows(lmdb, query, "irAggregate"));
				assertEquals(expected, rows(lmdb, query, "irAggregateInterpreted"));
			}
		} finally {
			try {
				lmdb.shutDown();
			} finally {
				try {
					memory.shutDown();
				} finally {
					previous.forEach((name, value) -> {
						if (value == null) {
							System.clearProperty(name);
						} else {
							System.setProperty(name, value);
						}
					});
				}
			}
		}
	}

	private static List<BindingSet> rows(SailRepository repository, String query, String route) {
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (route != null) {
				prepared.setForcedLmdbExecutionStrategy(route);
			}
			try (var result = prepared.evaluate()) {
				return QueryResults.asList(result);
			}
		}
	}

	private static void populate(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p = vf.createIRI(NS, "p"), q = vf.createIRI(NS, "q"), r = vf.createIRI(NS, "r"),
					t = vf.createIRI(NS, "t"), rejected = vf.createIRI(NS, "rejected");
			connection.begin();
			for (int i = 0; i < 5; i++) {
				IRI root = vf.createIRI(NS, "s" + i), a = vf.createIRI(NS, "a" + i),
						b = vf.createIRI(NS, "b" + i), c = vf.createIRI(NS, "c" + i);
				connection.add(root, RDF.TYPE, vf.createIRI(NS, "C"));
				connection.add(root, p, a);
				connection.add(a, q, b);
				connection.add(b, r, c);
				if (i == 0 || i == 1) {
					connection.add(c, t, rejected);
				}
				if (i != 1 && i != 2) {
					connection.add(c, t, vf.createIRI(NS, "d" + i));
				}
			}
			connection.commit();
		}
	}
}
